import{f as c,D as l,o as t,c as p,a2 as d,b as r,w as a,a as i,G as n,a6 as s}from"./chunks/framework.BUDOXiIz.js";const f=JSON.parse('{"title":"GoodApps Cooperativas","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/08-plan-puesta-en-marcha.md","filePath":"entregables-analisis-diseno/08-plan-puesta-en-marcha.md","lastUpdated":null}'),u={name:"entregables-analisis-diseno/08-plan-puesta-en-marcha.md"};function m(h,e,b,g,C,v){const o=l("Mermaid");return t(),p("div",null,[e[2]||(e[2]=d('<h1 id="goodapps-cooperativas" tabindex="-1">GoodApps Cooperativas <a class="header-anchor" href="#goodapps-cooperativas" aria-label="Permalink to &quot;GoodApps Cooperativas&quot;">​</a></h1><h2 id="plan-de-puesta-en-marcha-convivencia-con-procoop-capacitacion-y-gestion-del-cambio" tabindex="-1">Plan de puesta en marcha, convivencia con ProCoop, capacitación y gestión del cambio <a class="header-anchor" href="#plan-de-puesta-en-marcha-convivencia-con-procoop-capacitacion-y-gestion-del-cambio" aria-label="Permalink to &quot;Plan de puesta en marcha, convivencia con ProCoop, capacitación y gestión del cambio&quot;">​</a></h2><p><strong>Entregable de Análisis y Diseño Detallado — Artefactos 8.3 (Plan de puesta en marcha y convivencia) y 8.4 (Plan de capacitación y gestión del cambio)</strong></p><table tabindex="0"><thead><tr><th>Dato</th><th>Valor</th></tr></thead><tbody><tr><td>Producto</td><td>GoodApps Cooperativas: plataforma de gestión en la nube (SaaS multi-tenant) para cooperativas de servicios públicos y sociales</td></tr><tr><td>Documento</td><td>Plan de puesta en marcha, convivencia, capacitación y gestión del cambio</td></tr><tr><td>Destinatarios</td><td>Consejo de administración y gerencia de la cooperativa piloto, Laguna Larga (<code>LAG</code>, DEC-088), responsables de área, equipo de implementación y migración de la plataforma</td></tr><tr><td>Carácter</td><td>Documento derivado de la especificación vigente; no la reemplaza. Ante cualquier diferencia prevalecen la especificación maestra (<code>00</code>), sus anexos (en particular T07) y el registro de decisiones (<code>01</code>)</td></tr><tr><td>Versión</td><td>1.0</td></tr><tr><td>Fecha</td><td>05-11-2026</td></tr></tbody></table><h3 id="control-de-versiones" tabindex="-1">Control de versiones <a class="header-anchor" href="#control-de-versiones" aria-label="Permalink to &quot;Control de versiones&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Versión</th><th>Fecha</th><th>Descripción del cambio</th><th>Autor</th></tr></thead><tbody><tr><td>1.0</td><td>05-11-2026</td><td>Versión inicial del plan de puesta en marcha (8.3) y del plan de capacitación y gestión del cambio (8.4). Actualizada el mismo día por DEC-088 (cooperativa piloto: Laguna Larga), que reemplaza a DEC-081: supuestos, fases, validaciones, checklist, capacitación y puntos a definir</td><td></td></tr></tbody></table><h3 id="aprobaciones" tabindex="-1">Aprobaciones <a class="header-anchor" href="#aprobaciones" aria-label="Permalink to &quot;Aprobaciones&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rol</th><th>Nombre</th><th>Firma</th><th>Fecha</th></tr></thead><tbody><tr><td>Elaboró</td><td></td><td></td><td></td></tr><tr><td>Revisó</td><td></td><td></td><td></td></tr><tr><td>Aprobó</td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="indice" tabindex="-1">Índice <a class="header-anchor" href="#indice" aria-label="Permalink to &quot;Índice&quot;">​</a></h2><ol><li>Propósito, alcance y fuentes</li><li>Contexto y supuestos de la puesta en marcha</li><li>Estrategia de corte por etapas y convivencia con ProCoop</li><li>Fases de la puesta en marcha</li><li>Validaciones previas obligatorias</li><li>Checklist go/no-go</li><li>Plan de vuelta atrás</li><li>Comunicación a socios, entes y personal</li><li>Capacitación por rol</li><li>Gestión del cambio y soporte posterior al arranque</li><li>Matriz RACI resumida de la puesta en marcha</li><li>Indicadores de éxito del arranque</li><li>Puntos a definir y observaciones sobre las fuentes</li></ol><hr><h2 id="_1-proposito-alcance-y-fuentes" tabindex="-1">1. Propósito, alcance y fuentes <a class="header-anchor" href="#_1-proposito-alcance-y-fuentes" aria-label="Permalink to &quot;1. Propósito, alcance y fuentes&quot;">​</a></h2><p>Este documento describe cómo una cooperativa que hoy opera con ProCoop pasa a operar con GoodApps Cooperativas sin interrumpir su operación diaria y sin perder trazabilidad de saldos, documentos, equipos instalados ni datos históricos (T07 §1). Reúne en un plan de ejecución lo que la especificación define en T07 (estrategia, fases, conciliación, corte y vuelta atrás), en T08 (continuidad, soporte, seguridad y privacidad) y en el plan de olas <code>03</code> (criterio de salida de O11), y lo completa con la capacitación por rol y la gestión del cambio.</p><p>Las cifras, plazos y herramientas que no figuran en las fuentes se indican como <strong>a definir</strong>. No se fijan fechas: las olas no tienen fechas (DEC-006) y la especificación expresa los hitos como condiciones (RF-MIG-005).</p><p>Fuentes utilizadas:</p><table tabindex="0"><thead><tr><th>Fuente</th><th>Contenido que se toma</th></tr></thead><tbody><tr><td><code>anexos/T07-MIG-migracion-procoop.md</code> §4, §5.8, §5.9, §8, §9, §14, §15, §17</td><td>Roles, fases F1–F13, etapas E0–E4 de convivencia, conciliación, runbook de corte, criterios go, plan de retorno, parámetros e informes</td></tr><tr><td><code>anexos/T08-NFR-no-funcionales-seguridad.md</code> §8, §11.4, §15.8, §15.9, §19</td><td>Disponibilidad, restauración, guardia, soporte, indicadores y tratamiento de credenciales y usuarios en la migración</td></tr><tr><td><code>anexos/T01-PLA-plataforma-saas.md</code> §5.J, §7.10</td><td>Ambiente <code>sandbox</code> por cooperativa, anillos de actualización y notas de versión</td></tr><tr><td><code>00-ESPECIFICACION-MAESTRA.md</code> §1.4, §7.2, §14, §15</td><td>Piloto, catálogo de roles, RNF resumidos y olas</td></tr><tr><td><code>01-registro-decisiones.md</code></td><td>DEC-005, DEC-006, DEC-050, DEC-063, DEC-068, DEC-069, DEC-070, DEC-072, DEC-087, DEC-088 (reemplaza a DEC-081)</td></tr><tr><td><code>anexos/M07-COB-cuenta-corriente-cobranza.md</code> §17.6, CTR-COB-21, PA-COB-15, PA-COB-16; <code>anexos/M03-MED-medicion-consumos.md</code> §17; <code>anexos/M04-TAR-tarifas-motor-calculo.md</code> §17</td><td>Prepago disponible al migrar LAG, rendición Red Link y rama SIRO de LAG, y escenarios de servicios medidos</td></tr><tr><td><code>07-estrategia-pruebas.md</code> §15.2</td><td>Casos de aceptación de la migración de LAG (AC-16 a AC-20)</td></tr><tr><td><code>02-preguntas-abiertas.md</code></td><td>PA asumidas o respondidas que condicionan la puesta en marcha</td></tr><tr><td><code>05-registro-huecos.md</code></td><td>Los 8 parámetros con valor por defecto que requieren validación legal</td></tr><tr><td><code>03-plan-de-olas-y-prompts.md</code> §15</td><td>Criterio de salida de O11 (ensayos de corte y vuelta atrás)</td></tr></tbody></table><hr><h2 id="_2-contexto-y-supuestos-de-la-puesta-en-marcha" tabindex="-1">2. Contexto y supuestos de la puesta en marcha <a class="header-anchor" href="#_2-contexto-y-supuestos-de-la-puesta-en-marcha" aria-label="Permalink to &quot;2. Contexto y supuestos de la puesta en marcha&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N.º</th><th>Supuesto o condición</th><th>Fuente</th></tr></thead><tbody><tr><td>S-01</td><td>El primer flujo completo es el del servicio Internet; las olas O2 a O6 lo cierran y los servicios medidos llegan en O7</td><td>DEC-005; maestra §1.4</td></tr><tr><td>S-02</td><td>La cooperativa piloto, comercial y de migración, es <strong>Laguna Larga</strong> (<code>LAG</code>). Su base relevada sigue siendo la referencia para el mapeo, las pruebas de paralelo y los <code>[VERIFICAR]</code>; de ella solo se toma configuración, nunca datos personales. Las preguntas dirigidas &quot;a la cooperativa piloto&quot; se dirigen a LAG</td><td>DEC-088 (reemplaza a DEC-081)</td></tr><tr><td>S-03</td><td>La herramienta de migración se valida con datos sintéticos de Internet. LAG opera electricidad, gas y prepago, por lo que su primera migración real ocurre <strong>después de O7</strong></td><td>PA-MIG-17 (opción A, asumida por DEC-072); DEC-088; CTR-MIG-07</td></tr><tr><td>S-04</td><td>La venta prepaga debe estar disponible al migrar LAG: M07 deja el punto de cobro genérico en O5 y M03 adelanta solo el subconjunto prepago</td><td>CTR-COB-21; PA-COB-15 (asumida, DEC-072); RF-COB-075</td></tr><tr><td>S-05</td><td>El paralelo y el corte real de LAG incluyen electricidad, gas y prepago; el corte comercial de esos servicios ocurre al cerrar O7, con los ciclos de paralelo aprobados y el ensayo de corte con vuelta atrás probada (<code>03</code> §11.2), y el corte administrativo con apagado de ProCoop en O11 (<code>03</code> §15.2) (DEC-089; antes &quot;el corte avanza por etapas y por dominio hasta O11, cuyo criterio de salida exige los ensayos de corte comercial y administrativo con vuelta atrás probada&quot;, ver OBS-03)</td><td>DEC-088; DEC-068; DEC-089; T07 §9.1; <code>03</code> §11.2 y §15.2</td></tr><tr><td>S-06</td><td>El reemplazo de ProCoop es por etapas: primero el corte comercial (M01–M09) y luego el administrativo</td><td>DEC-068</td></tr><tr><td>S-07</td><td>La contabilidad oficial sigue en ProCoop hasta el corte administrativo; GoodApps contabiliza en un plan marcado no oficial, concilia contra ProCoop y se oficializa en el corte</td><td>DEC-069</td></tr><tr><td>S-08</td><td>La migración nunca escribe en la base de ProCoop (solo lectura en el origen)</td><td>RN-MIG-001; T07 §2.3</td></tr><tr><td>S-09</td><td>Cada cooperativa es un proyecto de migración independiente (un tenant); LAG es la primera y las siguientes reutilizan el conjunto de mapeo de plataforma</td><td>T07 §9.1</td></tr></tbody></table><hr><h2 id="_3-estrategia-de-corte-por-etapas-y-convivencia-con-procoop" tabindex="-1">3. Estrategia de corte por etapas y convivencia con ProCoop <a class="header-anchor" href="#_3-estrategia-de-corte-por-etapas-y-convivencia-con-procoop" aria-label="Permalink to &quot;3. Estrategia de corte por etapas y convivencia con ProCoop&quot;">​</a></h2><h3 id="_3-1-principio-rector" tabindex="-1">3.1 Principio rector <a class="header-anchor" href="#_3-1-principio-rector" aria-label="Permalink to &quot;3.1 Principio rector&quot;">​</a></h3><p>Durante toda la convivencia rige un <strong>único sistema de registro por dominio</strong>: está prohibido registrar el mismo hecho en ambos sistemas (por ejemplo, cobrar la misma factura en las dos cajas) (RN-MIG-031, RF-MIG-080). La unidad de migración, conciliación, paralelo y by-pass es el dominio (anexo dueño); un dominio se corta cuando su cargador, sus criterios de aceptación y los dominios de los que depende están aprobados (T07 §9.1).</p><h3 id="_3-2-etapas-de-convivencia-t07-§9-7" tabindex="-1">3.2 Etapas de convivencia (T07 §9.7) <a class="header-anchor" href="#_3-2-etapas-de-convivencia-t07-§9-7" aria-label="Permalink to &quot;3.2 Etapas de convivencia (T07 §9.7)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Etapa</th><th>GoodApps es maestro de</th><th>ProCoop es maestro de</th><th>Sincronización</th></tr></thead><tbody><tr><td>E0 Ensayos</td><td>Ninguno</td><td>Todos</td><td>Snapshots completos hacia un tenant de ensayo</td></tr><tr><td>E1 Paralelo comercial</td><td>Ninguno (GoodApps simula)</td><td>Todos</td><td>Delta diario ProCoop → GoodApps y comparación</td></tr><tr><td>E2 By-pass comercial (corte 1)</td><td>Personas, cuentas, contratos, catálogo, tarifas, medición, facturación, fiscal de ventas, cuenta corriente, cobranza, entes, mora, financiación, CRM, técnica, portal, comunicaciones</td><td>Compras, stock no serializado, tesorería, contabilidad oficial, sueldos, institucional y social (si no fueron cortados)</td><td>GoodApps → ProCoop: asientos resumidos diarios en formato importable, cobranzas para tesorería, retiros de materiales para stock, descuentos de empleados</td></tr><tr><td>E3 By-pass administrativo (corte 2)</td><td>Se agregan compras, stock, tesorería, contabilidad y retenciones</td><td>Sueldos, institucional y social, si no fueron cortados (ver OBS-01)</td><td>Los asientos de sueldos se importan en GoodApps desde ProCoop</td></tr><tr><td>E4 Apagado</td><td>Todos</td><td>Ninguno: ProCoop queda solo para consulta hasta el cierre del ejercicio y luego pasa a archivo</td><td>—</td></tr></tbody></table><p>El modo de sincronización adoptado es el delta unidireccional ProCoop → GoodApps mientras ProCoop es maestro y, luego, exportaciones GoodApps → ProCoop para los módulos que siguen en ProCoop (PA-MIG-03, asumida por DEC-072; RF-MIG-081, RF-MIG-082). El delta diario está parametrizado (PRM-MIG-043).</p><h3 id="_3-3-estado-de-cada-dominio-durante-la-convivencia" tabindex="-1">3.3 Estado de cada dominio durante la convivencia <a class="header-anchor" href="#_3-3-estado-de-cada-dominio-durante-la-convivencia" aria-label="Permalink to &quot;3.3 Estado de cada dominio durante la convivencia&quot;">​</a></h3>',28)),(t(),r(s,null,{default:a(()=>[n(o,{id:"mermaid-580",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20procoopMaster%0A%20%20%20%20procoopMaster%20--%3E%20parallel%20%3A%20Ensayo%20integral%20aprobado%0A%20%20%20%20parallel%20--%3E%20goodappsMaster%20%3A%20Paralelo%20y%20by-pass%20aprobados%0A%20%20%20%20goodappsMaster%20--%3E%20procoopOff%20%3A%20Apagado%20de%20ProCoop%0A%20%20%20%20goodappsMaster%20--%3E%20procoopMaster%20%3A%20Vuelta%20atr%C3%A1s%20aprobada%0A%20%20%20%20procoopOff%20--%3E%20%5B*%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d('<p>Estados de T07 §8.5; el retroceso desde <code>goodappsMaster</code> solo ocurre por vuelta atrás aprobada.</p><h3 id="_3-4-reglas-de-convivencia" tabindex="-1">3.4 Reglas de convivencia <a class="header-anchor" href="#_3-4-reglas-de-convivencia" aria-label="Permalink to &quot;3.4 Reglas de convivencia&quot;">​</a></h3><ol><li>Al cortar un dominio, ProCoop queda <strong>solo lectura</strong> para ese dominio; la cooperativa quita en ProCoop los permisos de alta y modificación (T07 §9.7; RF-MIG-006).</li><li>El portal CoopOnline se apaga en el corte comercial; los socios pasan al portal de GoodApps con sus usuarios migrados y sin contraseñas (T07 §9.7; RF-MIG-090; PA-MIG-07).</li><li>Los cobros que entran por entes con claves de ProCoop se resuelven con el resolutor de claves heredadas, que solo imputa a comprobantes impagos y ante ambigüedad genera un pago a cuenta con aviso (RF-MIG-083, RN-MIG-033). Los alias se mantienen hasta el vencimiento del último comprobante de ProCoop más 180 días (PRM-MIG-030; DEC-050; PA-MIG-16).</li><li>La caja de GoodApps lee los códigos de barras de ProCoop vigentes hasta que venzan esos comprobantes (RF-MIG-084); desde el corte, los comprobantes nuevos llevan un identificador de pago autocontenido (DEC-050; RF-MIG-085).</li><li>Las funciones de ProCoop atadas a la &quot;cuenta Procoop&quot; dependen de sus parámetros V2 518 y 519, que no deben modificarse durante la transición (T07 §9.7).</li><li>La forma de registrar las rendiciones bancarias (por caja o por fecha de acreditación) se acuerda con la contaduría antes del corte comercial (T07 §9.7).</li><li>LAG opera gas (DEC-088): el servicio de gas con sus exportaciones regulatorias debe estar en GoodApps antes del corte comercial (T07 §9.7).</li><li>La venta prepaga de LAG pasa a GoodApps junto con el corte comercial: el cobro lo hace M07 en caja y portal y la carga del crédito la hace M03 después de confirmado el cobro; si la carga falla, la recarga queda en bandeja sin generar un segundo token (RF-COB-075; CTR-COB-21; ESC-MED-22).</li><li>Las interfaces de LAG con entes recaudadores (rendición Red Link propia y rama SIRO) se configuran como perfiles de formato del conector y conviven con las claves heredadas de ProCoop según las reglas 3 y 4 (M07 §17.6; PA-COB-16).</li><li>Los números de cuenta de ProCoop se conservan como número visible (RN-MIG-050; PRM-MIG-002).</li></ol><hr><h2 id="_4-fases-de-la-puesta-en-marcha" tabindex="-1">4. Fases de la puesta en marcha <a class="header-anchor" href="#_4-fases-de-la-puesta-en-marcha" aria-label="Permalink to &quot;4. Fases de la puesta en marcha&quot;">​</a></h2><h3 id="_4-1-diagrama-de-fases" tabindex="-1">4.1 Diagrama de fases <a class="header-anchor" href="#_4-1-diagrama-de-fases" aria-label="Permalink to &quot;4.1 Diagrama de fases&quot;">​</a></h3>',6)),(t(),r(s,null,{default:a(()=>[n(o,{id:"mermaid-646",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20P0%5B%220.%20Herramienta%20validada%20con%20datos%20sint%C3%A9ticos%20de%20Internet%20-%20O0%20a%20O6%22%5D%20--%3E%20P1%5B%221.%20Preparaci%C3%B3n%20de%20LAG%22%5D%0A%20%20%20%20P1%20--%3E%20P2%5B%222.%20Perfilado%20y%20saneamiento%20de%20datos%20de%20LAG%22%5D%0A%20%20%20%20P2%20--%3E%20P3%5B%223.%20Migraciones%20de%20ensayo%20-%20E0%22%5D%0A%20%20%20%20P3%20--%3E%7C%22Rechazos%20o%20diferencias%22%7C%20P2%0A%20%20%20%20P3%20--%3E%7C%22Conciliaciones%20aprobadas%22%7C%20G0%7B%22O7%20aprobada%20y%20prepago%20disponible%22%7D%0A%20%20%20%20G0%20--%3E%7C%22No%22%7C%20P3%0A%20%20%20%20G0%20--%3E%7C%22S%C3%AD%22%7C%20P4%5B%224.%20Corrida%20paralela%20comercial%20de%20LAG%20con%20electricidad%2C%20gas%20y%20prepago%20-%20E1%22%5D%0A%20%20%20%20P4%20--%3E%7C%22Diferencias%20sin%20explicar%22%7C%20P3%0A%20%20%20%20P4%20--%3E%7C%22Paralelo%20aprobado%22%7C%20G1%7B%22Go%2Fno-go%20del%20corte%20comercial%22%7D%0A%20%20%20%20G1%20--%3E%7C%22No-go%22%7C%20P4%0A%20%20%20%20G1%20--%3E%7C%22Go%22%7C%20P5%5B%225a.%20Corte%20comercial%20-%20E2%22%5D%0A%20%20%20%20P5%20--%3E%20P6%5B%226.%20Hipercuidado%20del%20corte%20comercial%22%5D%0A%20%20%20%20P6%20--%3E%7C%22Incidente%20bloqueante%22%7C%20RB%5B%22Vuelta%20atr%C3%A1s%20seg%C3%BAn%20ventana%22%5D%0A%20%20%20%20RB%20--%3E%20P4%0A%20%20%20%20P6%20--%3E%20P7%5B%227.%20Estabilizaci%C3%B3n%20y%20convivencia%20administrativa%22%5D%0A%20%20%20%20P7%20--%3E%20G2%7B%22Go%2Fno-go%20del%20corte%20administrativo%22%7D%0A%20%20%20%20G2%20--%3E%7C%22No-go%22%7C%20P7%0A%20%20%20%20G2%20--%3E%7C%22Go%22%7C%20P8%5B%225b.%20Corte%20administrativo%20-%20E3%22%5D%0A%20%20%20%20P8%20--%3E%20P9%5B%226b.%20Hipercuidado%20del%20corte%20administrativo%22%5D%0A%20%20%20%20P9%20--%3E%20P10%5B%22Apagado%20de%20ProCoop%20-%20E4%20y%20cierre%20del%20proyecto%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<h3 id="_4-2-descripcion-de-las-fases" tabindex="-1">4.2 Descripción de las fases <a class="header-anchor" href="#_4-2-descripcion-de-las-fases" aria-label="Permalink to &quot;4.2 Descripción de las fases&quot;">​</a></h3><p>La correspondencia con las fases F1 a F13 de T07 §9.2 y con los estados del proyecto de migración (T07 §8.1) se indica en cada fila. La duración de cada fase es <strong>a definir</strong> (DEC-006).</p><p>Las fases 1 a 3 pueden avanzar a medida que se construyen los cargadores de cada dominio (la herramienta existe desde O0/O1 y cada cargador llega en la ola de su módulo; CTR-MIG-06). El paralelo y el corte real de LAG empiezan <strong>después de O7</strong>, porque LAG opera electricidad, gas y prepago, e incluyen esos tres servicios (PA-MIG-17; DEC-088; CTR-COB-21).</p><table tabindex="0"><thead><tr><th>Fase</th><th>Objetivo</th><th>Actividades principales</th><th>Salida verificable</th><th>Fases y estados de T07</th></tr></thead><tbody><tr><td>0. Validación de la herramienta</td><td>Probar la herramienta de migración antes de usar la base de LAG</td><td>Ensayos con datos sintéticos de Internet sobre TEN-001 (DEC-005; PA-MIG-17)</td><td>Herramienta aprobada para la primera migración real</td><td>Previa a F1</td></tr><tr><td>1. Preparación</td><td>Dejar listos el tenant de LAG, los accesos y las decisiones previas</td><td>Alta asistida del tenant y configuración publicada (hito de O1); creación del proyecto de migración (RF-MIG-001); inventario de fuentes con acceso de solo lectura (RF-MIG-002); sandbox de la cooperativa (RF-PLA-111); validaciones previas de la sección 5; plan de comunicación y de capacitación</td><td>Proyecto en <code>inventoried</code>; inventario de las 659 tablas con conteos</td><td>F1; <code>draft</code> → <code>inventoried</code></td></tr><tr><td>2. Perfilado y saneamiento de datos</td><td>Conocer y corregir la calidad de los datos heredados</td><td>Perfilado por tabla y columna (RF-MIG-020); validación de CUIT/DNI, duplicados y domicilios (T07 §9.5); mapeo de valores y publicación del conjunto de mapeo; cola de saneamiento con corrección en origen o en staging (RF-MIG-027, RF-MIG-028); resolución de los <code>[VERIFICAR]</code> de datos heredados; relevamiento del volumen de LAG por servicio (electricidad, gas y prepago)</td><td>Informe de perfilado con el volumen de LAG; conjunto de mapeo publicado; % de saneamiento por tipo</td><td>F2–F4; <code>mapping</code></td></tr><tr><td>3. Migraciones de ensayo</td><td>Probar la migración completa de forma repetible</td><td>Ensayos completos en tenant de ensayo (CU-MIG-02); reprocesos idempotentes; conciliaciones por dominio con muestreo (T07 §17.2); purga y repetición con nuevo snapshot hasta 0 rechazos bloqueantes; ensayo de corte cronometrado y de vuelta atrás (<code>03</code> §15.2); casos AC-16 a AC-19 de <code>07</code> §15.2 sobre la copia seudonimizada (PA-MIG-15)</td><td>Migración repetida dos veces con el mismo resultado; conciliaciones de personas, suministros, medición, tarifas y deuda aprobadas</td><td>F5–F9; <code>rehearsing</code></td></tr><tr><td>4. Corrida paralela</td><td>Demostrar que GoodApps factura igual que ProCoop o explica cada diferencia, en electricidad, gas y prepago</td><td>Empieza después de O7; simulación del ciclo sin efectos fiscales ni externos (RN-MIG-030); importación de lo emitido por ProCoop; comparación factura por factura y de mora, cobranzas y asientos (RF-MIG-072, RF-MIG-074); clasificación y explicación de diferencias; caso AC-20 de <code>07</code> §15.2 (ESC-COB-L05)</td><td>Paralelo aprobado por servicio: 2 ciclos consecutivos, 0 diferencias sin explicar, emparejamiento ≥ 99,9 % (T07 §17.4)</td><td>F10; <code>parallel</code></td></tr><tr><td>5a. Corte comercial</td><td>Pasar a GoodApps los dominios comerciales de LAG, incluidos electricidad, gas y la venta prepaga</td><td>Runbook de corte (sección 4.3); go/no-go con doble aprobación; acta de aceptación del alcance</td><td>Dominios comerciales en <code>goodappsMaster</code>; acta firmada (RF-MIG-087)</td><td>F11–F12; <code>bypassing</code> → <code>cutover</code> → <code>live</code></td></tr><tr><td>6. Hipercuidado</td><td>Acompañar los primeros ciclos reales con monitoreo reforzado</td><td>Monitoreo reforzado y soporte de arranque (T07 §9.9 paso 14; AGR §7 etapa F); seguimiento diario de alias, conciliaciones e invariantes; atención prioritaria de incidentes; decisión de vuelta atrás dentro de la ventana</td><td>Primer ciclo real de facturación y cobranza cerrado sin diferencias no explicadas (criterio de salida <strong>a definir</strong>)</td><td>Ventana <code>rollbackDeadline</code> (PRM-MIG-052)</td></tr><tr><td>7. Estabilización</td><td>Consolidar la operación y preparar el corte administrativo</td><td>Exportaciones diarias a ProCoop de asientos y cobranzas (RF-MIG-082); contabilidad no oficial conciliada contra ProCoop (DEC-069); preparación del corte administrativo con su propio go/no-go</td><td>Balance conciliado en el ensayo de corte administrativo (<code>03</code> §15.2)</td><td>Convivencia E2 → E3</td></tr><tr><td>5b y 6b. Corte administrativo e hipercuidado</td><td>Pasar compras, stock, tesorería, contabilidad y retenciones a GoodApps</td><td>Mismo runbook adaptado al alcance; oficialización del plan de cuentas (DEC-069); conciliación contable con diferencia 0 por cuenta (RF-MIG-057)</td><td>Acta del alcance administrativo</td><td>F11–F12</td></tr><tr><td>Apagado y cierre</td><td>Dejar ProCoop como archivo</td><td>ProCoop solo consulta hasta el cierre del ejercicio y luego archivo (E4); verificación del archivo; alias vencidos o programados</td><td>Proyecto en <code>closed</code>; snapshot archivado 10 años (DEC-070; PRM-MIG-015)</td><td><code>live</code> → <code>closed</code></td></tr></tbody></table><h3 id="_4-3-runbook-minimo-del-corte-t07-§9-9" tabindex="-1">4.3 Runbook mínimo del corte (T07 §9.9) <a class="header-anchor" href="#_4-3-runbook-minimo-del-corte-t07-§9-9" aria-label="Permalink to &quot;4.3 Runbook mínimo del corte (T07 §9.9)&quot;">​</a></h3><ol><li>Comunicación a socios y entes.</li><li>Verificar 0 comprobantes pendientes de CAE en ProCoop (RN-MIG-029).</li><li>Cierre de cajas en ProCoop.</li><li>Congelamiento del alcance (RF-MIG-006).</li><li>Snapshot <code>final</code>.</li><li>Delta final y carga.</li><li>Conciliaciones finales aprobadas.</li><li>Último número autorizado en ARCA por punto de venta (RN-MIG-028).</li><li>Go/no-go con doble aprobación (sección 6).</li><li>Activar emisión fiscal, publicación de deuda a entes, débitos, pasarelas y notificaciones.</li><li>Activar resolutor y alias de claves heredadas.</li><li>Habilitar el portal y enviar las invitaciones.</li><li>Acta de aceptación.</li><li>Monitoreo reforzado y soporte de arranque.</li></ol><p>La ventana horaria del corte es <strong>a definir</strong>; debe evitar los días críticos que la cooperativa declare (facturación masiva, primeros vencimientos, cierre de caja de fin de mes), según el calendario de congelamiento de RNF-NFR-034 (PA-NFR-12, asumida por DEC-072).</p><h3 id="_4-4-tratamiento-del-historico-tras-el-arranque" tabindex="-1">4.4 Tratamiento del histórico tras el arranque <a class="header-anchor" href="#_4-4-tratamiento-del-historico-tras-el-arranque" aria-label="Permalink to &quot;4.4 Tratamiento del histórico tras el arranque&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Categoría</th><th>Dónde queda</th><th>Fuente</th></tr></thead><tbody><tr><td>Datos vivos necesarios para operar el día siguiente al corte</td><td>Colección del módulo dueño, con <code>legacy</code></td><td>RN-MIG-004; T07 §9.4</td></tr><tr><td>Histórico tipado de solo lectura: ejercicio en curso más 24 meses</td><td>Colección del módulo dueño, con marca &quot;Migrado de ProCoop&quot;</td><td>DEC-070; RF-MIG-060</td></tr><tr><td>Histórico genérico consultable desde las fichas</td><td><code>legacyRecords</code></td><td>DEC-070; RF-MIG-061</td></tr><tr><td>Detalle accesorio de cobranzas de más de 36 meses</td><td>Archivo con consulta diferida; recibos, obligaciones, imputaciones y saldos nunca se archivan</td><td>DEC-087; T07 §9.4</td></tr><tr><td>Copia completa del origen (659 tablas y adjuntos)</td><td>Archivo cifrado con acceso auditado durante 10 años</td><td>DEC-070; RF-MIG-062</td></tr></tbody></table><hr><h2 id="_5-validaciones-previas-obligatorias" tabindex="-1">5. Validaciones previas obligatorias <a class="header-anchor" href="#_5-validaciones-previas-obligatorias" aria-label="Permalink to &quot;5. Validaciones previas obligatorias&quot;">​</a></h2><h3 id="_5-1-parametros-con-valor-por-defecto-que-requieren-validacion-legal" tabindex="-1">5.1 Parámetros con valor por defecto que requieren validación legal <a class="header-anchor" href="#_5-1-parametros-con-valor-por-defecto-que-requieren-validacion-legal" aria-label="Permalink to &quot;5.1 Parámetros con valor por defecto que requieren validación legal&quot;">​</a></h3><p><code>05-registro-huecos.md</code> resolvió 8 huecos con un parámetro cuyo valor por defecto debe validar el área legal antes de producción. Cada uno debe estar validado antes de activar en producción el servicio o la función a la que aplica:</p><table tabindex="0"><thead><tr><th>Hueco</th><th>Tema</th><th>Parámetros</th><th>Anexo</th><th>Ola</th><th>Validación indicada en la fuente</th><th>Aplica a la migración de LAG</th></tr></thead><tbody><tr><td>HUECO-CAP-04</td><td>Tratamiento fiscal del renglón de aporte de capital en la factura</td><td>PRM-FIS-122 (default <code>untaxedInInvoice</code>)</td><td>M06</td><td>O4</td><td>Encuadre fiscal con el contador</td><td>Sí, si LAG factura aportes de capital (a confirmar en el perfilado)</td></tr><tr><td>HUE-INT-03</td><td>Plazos de respuesta de reclamos TIC por motivo (Res. 733/2017)</td><td>PRM-CRM-132, PRM-CRM-135</td><td>M09</td><td>O2</td><td>Plazos ENACOM</td><td>Al servicio Internet validado con datos sintéticos; en LAG, solo si opera servicios TIC</td></tr><tr><td>HUE-GAS-05</td><td>Protocolo de emergencias de gas: guardias y tiempos</td><td>PRM-TEC-152, PRM-TEC-153, PRM-TEC-154, PRM-CRM-133</td><td>M10, M09</td><td>O7</td><td>Tiempos con la distribuidora y el regulador</td><td><strong>Sí</strong>: LAG opera gas (debe estar antes del corte comercial, sección 3.4)</td></tr><tr><td>HUE-AG-02</td><td>Restricción de caudal como modo de mora en agua</td><td>PRM-MOR-201 (caudal mínimo vital)</td><td>M08</td><td>O7</td><td>Caudal mínimo vital</td><td>Solo si LAG opera agua (DEC-088 no lo menciona)</td></tr><tr><td>HUE-ELE-05</td><td>Ventanas de corte por jurisdicción (ERSeP)</td><td>PRM-MOR-206 (plantilla <code>toValidate</code>)</td><td>M08</td><td>O7</td><td>Días, horarios y umbrales climáticos</td><td><strong>Sí</strong>: LAG opera electricidad</td></tr><tr><td>HUECO-SEP-01</td><td>Suspensión de cobertura social por cuotas impagas y carencia de rehabilitación</td><td>PRM-MOR-204, PRM-SOC-052</td><td>M08, M18</td><td>O10</td><td>Meses impagos y carencia según el reglamento</td><td>Solo si LAG opera servicios sociales</td></tr><tr><td>HUE-TEL-04</td><td>Mora de telefonía con llamadas de emergencia siempre habilitadas</td><td>PRM-MOR-199</td><td>M08</td><td>O10</td><td>Régimen de emergencias</td><td>Solo si LAG opera telefonía</td></tr><tr><td>HUE-TV-03</td><td>Mora de TV: corte total o grilla reducida</td><td>PRM-MOR-200</td><td>M08</td><td>O10</td><td>Grilla mínima</td><td>Solo si LAG opera TV</td></tr></tbody></table><p>Los servicios de LAG distintos de electricidad, gas y prepago no figuran en DEC-088; se confirman en el perfilado (fase 2).</p><p>Además, T08 cita normas marcadas <code>[VERIFICAR]</code> que deben revisarse con el área legal antes del arranque en lo que aplique a la cooperativa: artículos de la Ley 25.326 (RF-NFR-002, RF-NFR-006, RF-NFR-013), Ley 26.951 para comunicaciones promocionales (RF-NFR-005, PA-NFR-20), Ley 26.653 de accesibilidad web (RNF-NFR-180) y Ley 25.506 de firma digital (RNF-NFR-230).</p><h3 id="_5-2-verificaciones-verificar-de-datos-heredados" tabindex="-1">5.2 Verificaciones <code>[VERIFICAR]</code> de datos heredados <a class="header-anchor" href="#_5-2-verificaciones-verificar-de-datos-heredados" aria-label="Permalink to &quot;5.2 Verificaciones `[VERIFICAR]` de datos heredados&quot;">​</a></h3><p>Con DEC-088, la base relevada de Laguna Larga es a la vez la referencia del mapeo y la base de la cooperativa piloto; de ella solo se toma configuración, nunca datos personales. Los valores relevados deben confirmarse contra la base vigente de LAG durante el perfilado (fase 2):</p><table tabindex="0"><thead><tr><th>Regla</th><th>Qué se verifica</th><th>Fuente</th></tr></thead><tbody><tr><td>RN-MIG-002</td><td>Si la cooperativa tiene varias razones sociales en ProCoop, que se convierten en <code>legalEntities</code> del mismo tenant</td><td>T07 §6</td></tr><tr><td>RN-MIG-008</td><td>Reparto por servicio de pagos parciales históricos cuando ProCoop no lo discrimina (PRM-MIG-011)</td><td>T07 §6</td></tr><tr><td>RN-MIG-034</td><td>Facturas de una migración anterior a ProCoop (<code>FACTURAS.USUARIO</code>) y su criterio de exclusión regulatorio</td><td>T07 §6; RF-MIG-007</td></tr><tr><td>RN-MIG-048</td><td>Traducción de las fórmulas embebidas de ProCoop, con revisión humana y prueba en paralelo</td><td>T07 §6</td></tr><tr><td>RN-MIG-051</td><td>Valores de <code>IMPUESTO.ORIGEN</code> presentes en el tenant para clasificar tasas y tributos</td><td>T07 §6 (HUECO-TAS-03)</td></tr><tr><td>Perfilado F2</td><td>Facturas ≥ ARS 100.000 para códigos SIRO, uso de <code>FACTURAS.USUARIO</code> y rango de <code>COD_SUM</code></td><td>T07 §9.2</td></tr><tr><td>Parámetros V2</td><td>Mapeo de cada parámetro V2 al catálogo PRM; los que no tengan equivalente se registran para decisión</td><td>RN-MIG-049</td></tr><tr><td>Interfaces de cobranza de LAG</td><td>Estructura de la rendición Red Link propia, rama SIRO y tope del código de barras SIRO por vencimiento</td><td>M07 §17.6 (ESC-COB-L01, ESC-COB-L04); PA-COB-16</td></tr></tbody></table><h3 id="_5-3-validacion-de-pa-tes-17-con-el-contador" tabindex="-1">5.3 Validación de PA-TES-17 con el contador <a class="header-anchor" href="#_5-3-validacion-de-pa-tes-17-con-el-contador" aria-label="Permalink to &quot;5.3 Validación de PA-TES-17 con el contador&quot;">​</a></h3><p>PA-TES-17 (diferencia de arqueo en una rendición de caja con varias entidades jurídicas) está asumida con la opción recomendada: imputar a la entidad que indique el receptor, por defecto la de mayor importe rendido, con asiento entre entidades si corresponde (DEC-072). La propia fuente indica validarla con el contador de la cooperativa piloto, que con DEC-088 es el contador de LAG (M14 §21). Como la caja pasa a GoodApps en el corte comercial (E2), la validación debe completarse antes de ese go/no-go.</p><h3 id="_5-4-otras-decisiones-asumidas-a-confirmar-con-la-cooperativa" tabindex="-1">5.4 Otras decisiones asumidas a confirmar con la cooperativa <a class="header-anchor" href="#_5-4-otras-decisiones-asumidas-a-confirmar-con-la-cooperativa" aria-label="Permalink to &quot;5.4 Otras decisiones asumidas a confirmar con la cooperativa&quot;">​</a></h3><p>Son PA asumidas con la opción recomendada (DEC-072) que impactan directamente el arranque y conviene confirmar con LAG antes del go/no-go:</p><table tabindex="0"><thead><tr><th>PA</th><th>Opción asumida</th></tr></thead><tbody><tr><td>PA-MIG-17</td><td>Herramienta validada con datos sintéticos de Internet; primera migración real de LAG después de O7</td></tr><tr><td>PA-COB-15</td><td>M07 deja el cobro genérico en O5 y M03 adelanta solo el subconjunto prepago</td></tr><tr><td>PA-COB-16</td><td>Código de barras SIRO para importes ≥ ARS 100.000: formato extendido a acordar con el banco; mientras tanto, código electrónico y QR</td></tr><tr><td>PA-MIG-02</td><td>Paralelo de 2 ciclos consecutivos por servicio con 0 diferencias sin explicar</td></tr><tr><td>PA-MIG-05</td><td>Saldo de apertura de deuda documento por documento</td></tr><tr><td>PA-MIG-06</td><td>Intereses devengados al corte recalculados y conciliados contra ProCoop</td></tr><tr><td>PA-MIG-08</td><td>Mismos puntos de venta; continuar con el último número consultado a ARCA</td></tr><tr><td>PA-MIG-16</td><td>Alias de códigos ProCoop hasta el último vencimiento más 180 días</td></tr><tr><td>PA-NFR-12</td><td>Ventana de mantenimiento y congelamiento en días críticos</td></tr><tr><td>PA-NFR-17</td><td>Prueba de penetración externa antes del go-live del piloto</td></tr></tbody></table><p>PA-COB-15 figura como asumida en <code>02-preguntas-abiertas.md</code>, mientras que RF-COB-075 (punto de cobro de la venta prepaga) sigue &quot;A validar (PA-COB-15)&quot; en M07; su confirmación es condición del criterio GO-25.</p><hr><h2 id="_6-checklist-go-no-go" tabindex="-1">6. Checklist go/no-go <a class="header-anchor" href="#_6-checklist-go-no-go" aria-label="Permalink to &quot;6. Checklist go/no-go&quot;">​</a></h2><p>Se completa para cada corte (comercial y administrativo). Un solo criterio en rojo impide el corte (RF-MIG-086). La decisión exige doble aprobación y 2FA reciente (RN-MIG-041).</p><table tabindex="0"><thead><tr><th>N.º</th><th>Criterio</th><th>Evidencia</th><th>Fuente</th><th>Cumple (Sí/No)</th></tr></thead><tbody><tr><td>GO-01</td><td>Conciliaciones aprobadas de todos los dominios del alcance, por alguien distinto del ejecutor</td><td>Informes de conciliación firmados en el expediente</td><td>T07 §9.9; RF-MIG-053, RF-MIG-058</td><td></td></tr><tr><td>GO-02</td><td>Paralelo aprobado por servicio</td><td>Tablero de paralelo exportado</td><td>T07 §17.4; RF-MIG-075, RF-MIG-076</td><td></td></tr><tr><td>GO-03</td><td>Ensayo de corte cronometrado dentro de la ventana y vuelta atrás probada</td><td>Acta del ensayo</td><td><code>03</code> §15.2</td><td></td></tr><tr><td>GO-04</td><td>Usuarios y permisos cargados; MFA obligatorio para administradores; contraseñas de ProCoop no migradas</td><td>Revisión de la matriz de roles por la cooperativa</td><td>T07 §9.9; T08 §19</td><td></td></tr><tr><td>GO-05</td><td>Credenciales de integraciones nuevas cargadas en la bóveda y probadas; las anteriores revocadas ante el proveedor</td><td>Checklist de credenciales rotadas por conector</td><td>T07 §9.9; T08 §19; RN-MIG-013</td><td></td></tr><tr><td>GO-06</td><td>Clientes de API externos avisados y con tokens nuevos</td><td>Inventario de clientes externos</td><td>T08 §19; RNF-NFR-233</td><td></td></tr><tr><td>GO-07</td><td>Congelamiento del alcance confirmado por la cooperativa</td><td>Registro de congelamiento</td><td>RF-MIG-006</td><td></td></tr><tr><td>GO-08</td><td>0 comprobantes de ProCoop pendientes de CAE</td><td>Consulta en ProCoop</td><td>RN-MIG-029</td><td></td></tr><tr><td>GO-09</td><td>Cajas de ProCoop cerradas y autorizaciones pendientes cerradas o recreadas</td><td>Arqueos; cero pendientes al corte</td><td>T07 §9.9; T08 §19</td><td></td></tr><tr><td>GO-10</td><td>Último número autorizado consultado a ARCA por punto de venta y tipo</td><td>Resultado de la consulta</td><td>RN-MIG-028</td><td></td></tr><tr><td>GO-11</td><td>Validaciones legales aplicables al alcance completadas (sección 5.1)</td><td>Constancia del área legal</td><td><code>05-registro-huecos.md</code></td><td></td></tr><tr><td>GO-12</td><td><code>[VERIFICAR]</code> de datos heredados resueltos (sección 5.2)</td><td>Informe de perfilado</td><td>T07 §6, §9.2</td><td></td></tr><tr><td>GO-13</td><td>PA-TES-17 validada con el contador (corte comercial)</td><td>Constancia del contador</td><td>M14 §21</td><td></td></tr><tr><td>GO-14</td><td>Prueba de penetración sin hallazgos críticos ni altos abiertos</td><td>Informe y plan de remediación</td><td>RNF-NFR-095</td><td></td></tr><tr><td>GO-15</td><td>Simulacro de restauración del tenant de LAG vigente</td><td>Registro en <code>restoreTests</code></td><td>RNF-NFR-037, RNF-NFR-043</td><td></td></tr><tr><td>GO-16</td><td>Evidencia de liberación completa de la versión en producción</td><td><code>qualityEvidence</code> aprobada</td><td>RF-NFR-022, RNF-NFR-165</td><td></td></tr><tr><td>GO-17</td><td>Plan de vuelta atrás revisado y responsables designados</td><td>Plan aprobado</td><td>T07 §9.9, §9.11</td><td></td></tr><tr><td>GO-18</td><td>Soporte de arranque disponible y guardia organizada</td><td>Calendario de guardia</td><td>T07 §9.9; RNF-NFR-134</td><td></td></tr><tr><td>GO-19</td><td>Comunicación a socios y entes emitida (sección 8)</td><td>Registro de envíos y coordinación con entes</td><td>T07 §9.9; RF-MIG-085</td><td></td></tr><tr><td>GO-20</td><td>Capacitación por rol completada (sección 9)</td><td>Registro de asistencia y práctica (criterio <strong>a definir</strong>)</td><td>AGR §7 etapa F</td><td></td></tr><tr><td>GO-21</td><td>Registración bancaria de rendiciones acordada con la contaduría</td><td>Acuerdo documentado</td><td>T07 §9.7</td><td></td></tr><tr><td>GO-22</td><td>Gas de LAG: servicio, categorías y exportaciones regulatorias en GoodApps</td><td>Prueba en <code>sandbox</code>; caso AC-17 de <code>07</code> aprobado</td><td>T07 §9.7; ESC-TAR-38</td><td></td></tr><tr><td>GO-23</td><td>Ventana del corte fuera de los días críticos declarados</td><td>Calendario de congelamiento</td><td>RNF-NFR-034</td><td></td></tr><tr><td>GO-24</td><td>Corte administrativo: contabilidad no oficial conciliada y balance conciliado en el ensayo</td><td>Balance de sumas y saldos con diferencia 0</td><td>DEC-069; RF-MIG-057; <code>03</code> §15.2</td><td></td></tr><tr><td>GO-25</td><td>Prepago operativo: venta prepaga en caja y portal, carga del crédito en M03 después del cobro y bandeja de recargas fallidas sin segundo token; PA-COB-15 confirmada</td><td>Caso AC-16 de <code>07</code> aprobado (ESC-MED-22)</td><td>CTR-COB-21; PA-COB-15; RF-COB-075</td><td></td></tr><tr><td>GO-26</td><td>Servicios medidos de O7 aprobados: criterio de salida de O7 cumplido y paralelo de electricidad, gas y prepago aprobado</td><td>Acta de cierre de O7; tablero de paralelo por servicio; caso AC-20 de <code>07</code> aprobado (ESC-COB-L05)</td><td><code>03</code> §11.2; T07 §17.4; DEC-088</td><td></td></tr><tr><td>GO-27</td><td>Interfaces de cobranza de LAG probadas: rendición Red Link y rama SIRO, incluido el caso de importe ≥ ARS 100.000</td><td>Casos AC-18 y AC-19 de <code>07</code> aprobados (ESC-COB-L01, ESC-COB-L04)</td><td>M07 §17.6; PA-COB-16</td><td></td></tr></tbody></table><hr><h2 id="_7-plan-de-vuelta-atras" tabindex="-1">7. Plan de vuelta atrás <a class="header-anchor" href="#_7-plan-de-vuelta-atras" aria-label="Permalink to &quot;7. Plan de vuelta atrás&quot;">​</a></h2><p>El plan de retorno de la migración es distinto de la restauración de backups (T01) y del rollback de un despliegue (RNF-NFR-167). Su principio es que los hechos registrados en GoodApps después del corte no desaparecen si hay que volver a ProCoop (AGR-018; RF-MIG-088).</p><table tabindex="0"><thead><tr><th>Momento</th><th>Tratamiento</th><th>Fuente</th></tr></thead><tbody><tr><td>Antes del corte</td><td>No hay vuelta atrás: un dominio en paralelo simplemente no se corta</td><td>T07 §9.11</td></tr><tr><td>Entre el corte y <code>rollbackDeadline</code> (antes de la primera emisión fiscal real o del primer cobro por entes en GoodApps; PRM-MIG-052)</td><td>Se reabre ProCoop para el alcance, se exporta el diario <code>rollbackJournal</code> (altas, modificaciones, cobros en caja, lecturas) en formatos importables, se reprocesa en ProCoop y el dominio vuelve a <code>procoopMaster</code></td><td>T07 §9.11; RF-MIG-088; CU-MIG-11</td></tr><tr><td>Después de <code>rollbackDeadline</code></td><td>Solo vuelta atrás &quot;hacia adelante&quot;: se corrige en GoodApps; si se decide volver, los comprobantes autorizados y cobros confirmados se exportan a ProCoop como comprobantes de terceros o recibos manuales; nunca se restaura una copia que deshaga hechos fiscales o cobros externos. La interfaz bloquea la vuelta atrás por restauración</td><td>T07 §9.11; RF-MIG-089; AGR-019; ESC-MIG-09</td></tr></tbody></table><p>Reglas:</p><ul><li>Toda decisión de vuelta atrás requiere doble aprobación, 2FA y queda en el expediente (T07 §9.11; RN-MIG-041).</li><li>La aprueba el responsable de la cooperativa (<code>mig.rollback.aprobar</code>) y la ejecuta el líder de migración (<code>mig.rollback.ejecutar</code>) (T07 §4).</li><li>Los criterios concretos que disparan la evaluación de una vuelta atrás (tipo y gravedad del incidente bloqueante) son <strong>a definir</strong>; se propone usar como referencia la severidad SEV1 de RNF-NFR-134.</li><li>La vuelta atrás se ensaya en O11 como parte del criterio de salida de la ola (<code>03</code> §15.2).</li></ul><hr><h2 id="_8-comunicacion-a-socios-entes-y-personal" tabindex="-1">8. Comunicación a socios, entes y personal <a class="header-anchor" href="#_8-comunicacion-a-socios-entes-y-personal" aria-label="Permalink to &quot;8. Comunicación a socios, entes y personal&quot;">​</a></h2><h3 id="_8-1-mensajes-por-destinatario" tabindex="-1">8.1 Mensajes por destinatario <a class="header-anchor" href="#_8-1-mensajes-por-destinatario" aria-label="Permalink to &quot;8.1 Mensajes por destinatario&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Destinatario</th><th>Qué se comunica</th><th>Canal según fuentes</th><th>Fuente</th></tr></thead><tbody><tr><td>Socios</td><td>Habilitación del nuevo portal e invitación de activación sin necesidad de registrarse de nuevo; apagado de CoopOnline</td><td>Correo o SMS de invitación; landing y muro editorial; motor de comunicaciones de T09</td><td>RF-MIG-090; PA-MIG-07; T07 §9.7; DEC-008</td></tr><tr><td>Socios</td><td>Se conserva el número de cuenta</td><td>Mismos canales</td><td>RN-MIG-050</td></tr><tr><td>Socios</td><td>Las facturas de ProCoop impagas se siguen pudiendo pagar en caja y por entes; los comprobantes nuevos traen un identificador de pago nuevo</td><td>Mismos canales y mensaje en caja</td><td>RF-MIG-083, RF-MIG-084, RF-MIG-085; DEC-050</td></tr><tr><td>Socios</td><td>Las facturas y pagos históricos quedan visibles en el portal</td><td>Portal</td><td>RF-MIG-063</td></tr><tr><td>Socios</td><td>Solicitud de consentimientos en el primer acceso para las finalidades que lo requieran</td><td>Portal</td><td>T08 §19</td></tr><tr><td>Socios de LAG con medidor prepago</td><td>Dónde y cómo comprar crédito en GoodApps (caja y portal) desde el corte comercial</td><td>Mismos canales y mensaje en caja</td><td>RF-COB-075; CTR-COB-21</td></tr><tr><td>Entes recaudadores (Red Link, SIRO y otros)</td><td>Nuevo identificador autocontenido y convivencia con el padrón anterior hasta el vencimiento de lo emitido por ProCoop</td><td>Coordinación directa</td><td>RF-MIG-085</td></tr><tr><td>Pasarelas y proveedores de integración</td><td>Rotación de credenciales y alta de las nuevas en la bóveda</td><td>Coordinación directa</td><td>T08 §19</td></tr><tr><td>Clientes de API externos</td><td>Emisión de tokens nuevos y revocación de los anteriores al by-pass</td><td>Aviso a cada cliente</td><td>T08 §19</td></tr><tr><td>Personal de la cooperativa</td><td>Calendario de corte, congelamiento de ProCoop por dominio, cambios de procedimiento, capacitación y canal de soporte</td><td>Avisos internos solo para empleados; novedades del proveedor en el admin</td><td>M19 CU-NOT-01; RF-PLA-108</td></tr><tr><td>Todos</td><td>Mantenimientos programados e incidentes</td><td>Página de estado y aviso en el admin</td><td>RF-NFR-019 (A validar, PA-NFR-15); RF-PLA-151</td></tr></tbody></table><h3 id="_8-2-reglas" tabindex="-1">8.2 Reglas <a class="header-anchor" href="#_8-2-reglas" aria-label="Permalink to &quot;8.2 Reglas&quot;">​</a></h3><ul><li>Las comunicaciones tienen estados verificables; un mensaje regulado no se da por cumplido con &quot;aceptado por el proveedor&quot; (RNF-NFR-253).</li><li>Para cambios visibles de las versiones del producto rige el aviso de RNF-NFR-172 (≥ 7 días para cambios visibles relevantes y ≥ 30 días para cambios de cálculo o de API externa).</li><li>La anticipación de las comunicaciones del corte, el cronograma de envíos y los textos son <strong>a definir</strong> con LAG.</li></ul><hr><h2 id="_9-capacitacion-por-rol" tabindex="-1">9. Capacitación por rol <a class="header-anchor" href="#_9-capacitacion-por-rol" aria-label="Permalink to &quot;9. Capacitación por rol&quot;">​</a></h2><h3 id="_9-1-recursos-que-la-especificacion-ya-preve" tabindex="-1">9.1 Recursos que la especificación ya prevé <a class="header-anchor" href="#_9-1-recursos-que-la-especificacion-ya-preve" aria-label="Permalink to &quot;9.1 Recursos que la especificación ya prevé&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Recurso</th><th>Uso en la capacitación</th><th>Fuente</th></tr></thead><tbody><tr><td>Ambiente <code>sandbox</code> con tenant gemelo de la cooperativa e integraciones solo en homologación</td><td>Práctica guiada sin riesgo sobre la configuración propia</td><td>RF-PLA-111; PA-PLA-06</td></tr><tr><td>Copia anonimizada para ensayo y capacitación, con seudonimización irreversible</td><td>Práctica con datos realistas sin datos personales reales</td><td>PA-MIG-15; RF-MIG-095</td></tr><tr><td>Ayuda contextual <code>ScreenHelp</code> en cada pantalla (qué, quién, cuándo, dónde, por qué, cómo y caso de uso), editable por la cooperativa</td><td>Material de consulta en el puesto de trabajo</td><td>RF-UXD-049; PAN-UXD-06</td></tr><tr><td>Casos de uso y escenarios de la sección 16 y 17 de cada anexo</td><td>Guiones de práctica por rol</td><td>Anexos M01–M19, T07</td></tr><tr><td>Diccionario de términos por tenant</td><td>Vocabulario propio de la cooperativa en la interfaz y en los materiales</td><td>Maestra §1.3 P3; T03</td></tr><tr><td>Notas de versión y novedades del proveedor</td><td>Actualización continua posterior al arranque</td><td>RF-PLA-108</td></tr><tr><td>Avisos internos y eventos de tipo &quot;capacitación&quot; en la comunidad</td><td>Convocatorias</td><td>M19 CU-NOT-01; RF-COM-100</td></tr></tbody></table><h3 id="_9-2-plan-por-rol" tabindex="-1">9.2 Plan por rol <a class="header-anchor" href="#_9-2-plan-por-rol" aria-label="Permalink to &quot;9.2 Plan por rol&quot;">​</a></h3><p>Los destinatarios son el personal de LAG (DEC-088) y sus socios. La modalidad indicada es una <strong>propuesta</strong> de este documento basada en los recursos anteriores; la cantidad de personas por rol se conoce en la preparación (fase 1), y la carga horaria, los grupos, el calendario y el criterio de aprobación son <strong>a definir</strong>. Para los servicios medidos y el prepago, la capacitación se hace después de O7, antes del paralelo (fase 4).</p><table tabindex="0"><thead><tr><th>Destinatarios en LAG (roles de la maestra §7.2)</th><th>Contenidos clave</th><th>Modalidad propuesta</th><th>Materiales</th></tr></thead><tbody><tr><td>Administración: Administrador de la cooperativa (T-ADM) y Administrador de usuarios (T-USR)</td><td>Usuarios, roles, alcance y 2FA; configuración versionada con aprobación y reversión; diccionario y marca; prueba en sandbox y promoción a producción; tablero de salud del tenant; bandeja de solicitudes de derechos</td><td>Práctica guiada en <code>sandbox</code></td><td><code>ScreenHelp</code>; casos de T01, T02, T03, T04 y T08 (RF-NFR-006, RF-NFR-017)</td></tr><tr><td>Caja: Cajero (T-CAJ), Cobrador (T-CBR) y Tesorero (T-TES)</td><td>Apertura y cierre de caja; cobro y arqueo; lectura de códigos de barras de ProCoop y pago a cuenta ante ambigüedad; diferencia de arqueo con varias entidades (PA-TES-17); venta prepaga y tratamiento de una recarga que queda en bandeja; rendiciones Red Link y SIRO de LAG; los cobros no se registran sin conexión</td><td>Práctica guiada en <code>sandbox</code> con lector en el puesto</td><td><code>ScreenHelp</code>; CU-MIG-08, CU-MIG-09; escenarios de M07 §17 (ESC-COB-L01 a ESC-COB-L05); ESC-MED-22</td></tr><tr><td>Atención: Comercial / Atención al socio (T-ATE) y Supervisor de atención (T-SAT)</td><td>Ficha del socio y de la cuenta; solicitudes y reclamos, incluido el protocolo de emergencias de gas (HUE-GAS-05); baja sin cargo ni condicionamiento; consulta del histórico de ProCoop desde la ficha; acompañamiento al socio en la activación del portal; la IA solo propone</td><td>Práctica guiada en <code>sandbox</code></td><td><code>ScreenHelp</code>; ESC-CRM-04; RF-MIG-061; casos de M01, M09 y M19</td></tr><tr><td>Técnicos de campo: Técnico (T-TEC), Lecturista (T-LEC) y Supervisor técnico (T-STE)</td><td>PWA de campo sin conexión; sincronización y resolución de conflictos; comodato, firma y fotos; actualización de la app sin perder la cola; rutas de lectura de electricidad y gas, lectura menor que la anterior y medidor inaccesible</td><td>Práctica en dispositivo con red simulada o desconectada, sobre una ruta de lectura ficticia</td><td><code>ScreenHelp</code>; ESC-TEC-08, ESC-TEC-09; ESC-MED-05, ESC-MED-06; RF-PLA-150; <code>03</code> §11.2</td></tr><tr><td>Contabilidad: Contador (T-CON) y Tesorero (T-TES)</td><td>Plan de cuentas no oficial durante la convivencia y oficialización en el corte administrativo; aprobación de conciliaciones y saldos iniciales; justificación de diferencias del paralelo; exportación de asientos a ProCoop</td><td>Taller con los informes reales de conciliación del ensayo</td><td>DEC-069; RF-MIG-054 a 057, RF-MIG-082; informes de T07 §15</td></tr><tr><td>Socios en el portal: Socio titular (C-SOC) y Representante (C-REP)</td><td>Activación de la cuenta por invitación; cuentas vinculadas; facturas, historial y pago; consumos y compra de crédito prepago; reclamos; &quot;Mis datos y privacidad&quot;</td><td>Autoayuda en la PWA y apoyo de atención en el mostrador</td><td><code>ScreenHelp</code>; guía breve para socios (<strong>a definir</strong>); RF-NFR-012</td></tr></tbody></table><p>Otros roles (por ejemplo Facturación T-FAC, Compras T-CMP, Depósito T-DEP, RRHH T-RRHH) se capacitan con el mismo esquema antes del corte en que su dominio pasa a GoodApps; su detalle es <strong>a definir</strong>.</p><h3 id="_9-3-capacitacion-del-equipo-de-migracion-de-la-cooperativa" tabindex="-1">9.3 Capacitación del equipo de migración de la cooperativa <a class="header-anchor" href="#_9-3-capacitacion-del-equipo-de-migracion-de-la-cooperativa" aria-label="Permalink to &quot;9.3 Capacitación del equipo de migración de la cooperativa&quot;">​</a></h3><p>El analista de datos, los responsables funcionales de dominio y el contador operan la herramienta de migración desde la vista del tenant (T07 §4, §10): cola de saneamiento, informes de rechazos y conciliaciones, justificación de diferencias del paralelo y aprobaciones. Se capacitan durante las fases 2 y 3, sobre los propios ensayos.</p><hr><h2 id="_10-gestion-del-cambio-y-soporte-posterior-al-arranque" tabindex="-1">10. Gestión del cambio y soporte posterior al arranque <a class="header-anchor" href="#_10-gestion-del-cambio-y-soporte-posterior-al-arranque" aria-label="Permalink to &quot;10. Gestión del cambio y soporte posterior al arranque&quot;">​</a></h2><h3 id="_10-1-gestion-del-cambio" tabindex="-1">10.1 Gestión del cambio <a class="header-anchor" href="#_10-1-gestion-del-cambio" aria-label="Permalink to &quot;10.1 Gestión del cambio&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Línea de acción</th><th>Contenido</th><th>Fuente</th></tr></thead><tbody><tr><td>Patrocinio</td><td>El responsable de la cooperativa (gerencia o consejo) aprueba paralelo, by-pass, corte y vuelta atrás y firma el acta</td><td>T07 §4</td></tr><tr><td>Vocabulario propio</td><td>Cada cooperativa adapta sus términos (socio, usuario, asociado) desde el inicio</td><td>Maestra §1.3 P3</td></tr><tr><td>Simplicidad para el socio</td><td>Una tarea principal por pantalla y autogestión en el celular</td><td>Maestra §1.3 P7</td></tr><tr><td>Continuidad para el socio</td><td>Mismo número de cuenta, usuarios del portal sin nuevo registro, facturas viejas pagables</td><td>RN-MIG-050; RF-MIG-090; RF-MIG-084</td></tr><tr><td>Adopción gradual</td><td>Funcionalidades habilitadas primero para la cooperativa piloto (LAG) mediante anillos y feature flags</td><td>RF-PLA-149; RNF-NFR-169</td></tr><tr><td>Práctica sin riesgo</td><td>Sandbox de la cooperativa antes de publicar configuración</td><td>RF-PLA-111</td></tr><tr><td>Riesgo identificado</td><td>Resistencia al cambio del personal y baja adopción digital de los socios (R-05)</td><td><code>01-resumen-ejecutivo-vision.md</code></td></tr><tr><td>Referentes o usuarios clave por área</td><td>Designación y rol en la adopción</td><td><strong>A definir</strong></td></tr><tr><td>Medición de la adopción</td><td>Utilidad de las ayudas (IND-UXD-05) y otros indicadores de la sección 12</td><td>T03 §15</td></tr></tbody></table><h3 id="_10-2-soporte-posterior-al-arranque" tabindex="-1">10.2 Soporte posterior al arranque <a class="header-anchor" href="#_10-2-soporte-posterior-al-arranque" aria-label="Permalink to &quot;10.2 Soporte posterior al arranque&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Elemento</th><th>Definición</th><th>Fuente</th></tr></thead><tbody><tr><td>Horario de soporte</td><td>Lunes a viernes 8 a 18, con atención 24×7 para P1</td><td>DEC-063</td></tr><tr><td>Primera respuesta por severidad del ticket</td><td>Crítica ≤ 1 h 24×7; Alta ≤ 4 h hábiles; Media ≤ 1 día hábil; Baja ≤ 3 días hábiles</td><td>RNF-NFR-252</td></tr><tr><td>Guardia de incidentes</td><td>SEV1 reconocimiento ≤ 15 min 24×7; SEV2 ≤ 30 min 24×7; SEV3 ≤ 4 h hábiles; SEV4 ≤ 2 días hábiles; post-mortem para SEV1 y SEV2</td><td>RNF-NFR-134</td></tr><tr><td>Diagnóstico</td><td>Por <code>correlationId</code>, sin acceder a datos personales salvo acceso temporal consentido y auditado</td><td>RNF-NFR-252, RNF-NFR-257; AGR-034</td></tr><tr><td>Monitoreo reforzado del arranque</td><td>Tablero de salud del tenant (lotes, emisión fiscal, cobranzas e inciertos, conectores), bandeja de operaciones detenidas, informe de uso de alias, verificación diaria de invariantes</td><td>T07 §9.9 paso 14; RF-NFR-017; RNF-NFR-222; T07 §15; RNF-NFR-229</td></tr><tr><td>Primera línea de soporte dentro de la cooperativa</td><td>Quién atiende primero las consultas internas y de socios</td><td><strong>A definir</strong></td></tr><tr><td>Duración del hipercuidado y criterio de salida</td><td>—</td><td><strong>A definir</strong></td></tr></tbody></table><hr><h2 id="_11-matriz-raci-resumida-de-la-puesta-en-marcha" tabindex="-1">11. Matriz RACI resumida de la puesta en marcha <a class="header-anchor" href="#_11-matriz-raci-resumida-de-la-puesta-en-marcha" aria-label="Permalink to &quot;11. Matriz RACI resumida de la puesta en marcha&quot;">​</a></h2><p>R = realiza; A = aprueba y rinde cuentas; C = consultado; I = informado. Derivada de los roles y capabilities de T07 §4 y del responsable de cada fase de T07 §9.2; las celdas sin respaldo directo en las fuentes son una propuesta de este documento. La RACI general del proyecto corresponde al artefacto 1.4 (<code>09-riesgos-y-raci.md</code>).</p><table tabindex="0"><thead><tr><th>Actividad</th><th>Líder de migración (plataforma)</th><th>Implementador (plataforma)</th><th>Analista de datos (cooperativa)</th><th>Responsable funcional de dominio</th><th>Contador de la cooperativa</th><th>Responsable de la cooperativa</th><th>Administrador de la cooperativa (T-ADM)</th><th>Soporte y operaciones de plataforma</th><th>Área legal</th></tr></thead><tbody><tr><td>Inventario y perfilado (F1–F2)</td><td>A</td><td>R</td><td>R</td><td>C</td><td>I</td><td>I</td><td>I</td><td>—</td><td>—</td></tr><tr><td>Mapeo y saneamiento (F3–F4)</td><td>A</td><td>R</td><td>R</td><td>C</td><td>C</td><td>I</td><td>I</td><td>—</td><td>—</td></tr><tr><td>Ensayos de migración (F5–F9)</td><td>A</td><td>R</td><td>C</td><td>C</td><td>C</td><td>I</td><td>I</td><td>C</td><td>—</td></tr><tr><td>Aprobación de conciliaciones por dominio</td><td>I</td><td>C</td><td>C</td><td>A/R</td><td>A/R (COB, CON, FIS, TES, SUE)</td><td>I</td><td>—</td><td>—</td><td>—</td></tr><tr><td>Corrida paralela y justificación de diferencias (F10)</td><td>R</td><td>R</td><td>C</td><td>R</td><td>C</td><td>A</td><td>—</td><td>—</td><td>—</td></tr><tr><td>Validación de parámetros legales</td><td>I</td><td>C</td><td>—</td><td>C</td><td>C</td><td>A</td><td>I</td><td>—</td><td>R</td></tr><tr><td>Validación de PA-TES-17</td><td>I</td><td>C</td><td>—</td><td>C</td><td>R</td><td>A</td><td>—</td><td>—</td><td>—</td></tr><tr><td>Usuarios, roles y permisos</td><td>C</td><td>C</td><td>—</td><td>C</td><td>—</td><td>I</td><td>R</td><td>—</td><td>—</td></tr><tr><td>Go/no-go del corte</td><td>R</td><td>C</td><td>C</td><td>C</td><td>C</td><td>A</td><td>C</td><td>C</td><td>C</td></tr><tr><td>Ejecución del corte (runbook)</td><td>R/A</td><td>R</td><td>C</td><td>C</td><td>C</td><td>I</td><td>C</td><td>R</td><td>—</td></tr><tr><td>Vuelta atrás</td><td>R</td><td>R</td><td>C</td><td>C</td><td>C</td><td>A</td><td>C</td><td>R</td><td>—</td></tr><tr><td>Comunicación a socios y entes</td><td>C</td><td>C</td><td>—</td><td>C</td><td>—</td><td>A</td><td>R</td><td>—</td><td>C</td></tr><tr><td>Capacitación por rol</td><td>C</td><td>R</td><td>—</td><td>C</td><td>C</td><td>A</td><td>R</td><td>—</td><td>—</td></tr><tr><td>Hipercuidado y soporte</td><td>R</td><td>R</td><td>C</td><td>C</td><td>C</td><td>I</td><td>C</td><td>R</td><td>—</td></tr><tr><td>Apagado de ProCoop y cierre del proyecto</td><td>R</td><td>C</td><td>—</td><td>C</td><td>C</td><td>A</td><td>I</td><td>C</td><td>—</td></tr></tbody></table><hr><h2 id="_12-indicadores-de-exito-del-arranque" tabindex="-1">12. Indicadores de éxito del arranque <a class="header-anchor" href="#_12-indicadores-de-exito-del-arranque" aria-label="Permalink to &quot;12. Indicadores de éxito del arranque&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Indicador</th><th>Fórmula o fuente</th><th>Meta</th><th>Origen de la meta</th></tr></thead><tbody><tr><td>Disponibilidad mensual</td><td>IND-NFR-01</td><td>99,5 %</td><td>DEC-063</td></tr><tr><td>Latencia p95 de pantallas interactivas</td><td>IND-NFR-02</td><td>≤ 800 ms</td><td>DEC-063</td></tr><tr><td>Diferencias de invariantes por tenant</td><td>IND-NFR-12 (JOB-NFR-06)</td><td>0 no explicadas</td><td>RNF-NFR-229</td></tr><tr><td>Conciliaciones finales aprobadas</td><td>Dominios del alcance con conciliación aprobada ÷ dominios del alcance</td><td>100 %</td><td>RF-MIG-053</td></tr><tr><td>Paralelo aprobado</td><td>Informe &quot;Paralelo factura por factura&quot; y &quot;Tendencia de paralelo&quot;</td><td>0 diferencias sin explicar; emparejamiento ≥ 99,9 %</td><td>T07 §17.4; PRM-MIG-042</td></tr><tr><td>Primera respuesta de soporte en plazo</td><td>IND-NFR-17</td><td>≥ 95 %</td><td>RNF-NFR-252</td></tr><tr><td>Alertas reconocidas en plazo</td><td>IND-NFR-05</td><td>≥ 95 %</td><td>RNF-NFR-134</td></tr><tr><td>Tasa de éxito de autorización ARCA</td><td>IND-NFR-06</td><td><strong>A definir</strong></td><td>—</td></tr><tr><td>Pagos con clave heredada resueltos, ambiguos y no resueltos</td><td>Informe &quot;Uso de alias&quot;</td><td><strong>A definir</strong></td><td>T07 §15 (indicador sin meta)</td></tr><tr><td>Rendimiento web percibido</td><td>IND-NFR-15</td><td>LCP ≤ 2,5 s; INP ≤ 200 ms; CLS ≤ 0,1</td><td>RNF-NFR-008</td></tr><tr><td>Socios que activaron el portal sobre socios invitados</td><td>—</td><td><strong>A definir</strong></td><td>No está en las fuentes</td></tr><tr><td>Utilidad de las ayudas contextuales</td><td>IND-UXD-05</td><td><strong>A definir</strong></td><td>T03 §15 (indicador sin meta)</td></tr><tr><td>Primer ciclo real de facturación y cobranza cerrado en GoodApps</td><td>—</td><td><strong>A definir</strong></td><td>No está en las fuentes</td></tr><tr><td>Volumen de tickets por área durante el hipercuidado</td><td>—</td><td><strong>A definir</strong></td><td>No está en las fuentes</td></tr></tbody></table><hr><h2 id="_13-puntos-a-definir-y-observaciones-sobre-las-fuentes" tabindex="-1">13. Puntos a definir y observaciones sobre las fuentes <a class="header-anchor" href="#_13-puntos-a-definir-y-observaciones-sobre-las-fuentes" aria-label="Permalink to &quot;13. Puntos a definir y observaciones sobre las fuentes&quot;">​</a></h2><h3 id="_13-1-puntos-a-definir" tabindex="-1">13.1 Puntos a definir <a class="header-anchor" href="#_13-1-puntos-a-definir" aria-label="Permalink to &quot;13.1 Puntos a definir&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º</th><th>Punto</th><th>Situación en las fuentes</th></tr></thead><tbody><tr><td>AD-01</td><td>Duración de cada fase y calendario general</td><td>Sin fechas (DEC-006); hitos expresados como condiciones</td></tr><tr><td>AD-02</td><td>Volumen de LAG (por servicio y por dominio)</td><td>A relevar en el perfilado (fase 2); las fuentes no dan cifras</td></tr><tr><td>AD-03</td><td>Ventana horaria de cada corte</td><td>Debe respetar el calendario de congelamiento (RNF-NFR-034); horario no definido</td></tr><tr><td>AD-04</td><td>Duración del hipercuidado y criterio de salida</td><td>El runbook prevé monitoreo reforzado y soporte de arranque (T07 §9.9) sin duración</td></tr><tr><td>AD-05</td><td>Criterios concretos que disparan la evaluación de una vuelta atrás</td><td>La fuente habla de &quot;incidente bloqueante&quot; (T07 §9.2 F13)</td></tr><tr><td>AD-06</td><td>Anticipación, cronograma y textos de la comunicación del corte</td><td>El runbook incluye la comunicación (T07 §9.9) sin plazos</td></tr><tr><td>AD-07</td><td>Carga horaria, grupos, calendario y criterio de aprobación de la capacitación</td><td>No definidos</td></tr><tr><td>AD-08</td><td>Guía breve para socios y materiales específicos por rol</td><td>Solo están previstos <code>ScreenHelp</code>, sandbox y casos de uso</td></tr><tr><td>AD-09</td><td>Referentes por área y primera línea de soporte en la cooperativa</td><td>No definidos</td></tr><tr><td>AD-10</td><td>Metas de los indicadores marcados &quot;a definir&quot; en la sección 12</td><td>No definidas</td></tr><tr><td>AD-11</td><td>Asignación nominal de personas a los roles de la RACI, del lado de LAG y de la plataforma</td><td>No definida</td></tr><tr><td>AD-12</td><td>Momento del corte comercial de LAG entre el cierre de O7 y O11</td><td>DEC-088 indica que el corte avanza por etapas hasta O11; no fija cuándo ocurre el corte comercial (ver OBS-03). <strong>Resuelto (DEC-089):</strong> electricidad, gas y prepago se cortan tras el cierre de O7 con 2 ciclos de paralelo aprobados; otros servicios, al cierre de la ola de su vertical; corte administrativo en O11</td></tr><tr><td>AD-13</td><td>Servicios de LAG además de electricidad, gas y prepago</td><td>DEC-088 menciona solo esos tres; se confirman en el perfilado y definen qué validaciones de la sección 5.1 aplican. <strong>Resuelto (DEC-089):</strong> confirmados electricidad (con prepago) y gas por redes; el resto sale del catálogo de servicios de <code>PR_LAG_DEMO</code> en el perfilado y ya está cubierto por T12</td></tr></tbody></table><h3 id="_13-2-observaciones-sobre-las-fuentes-para-validar-no-se-modificaron" tabindex="-1">13.2 Observaciones sobre las fuentes (para validar; no se modificaron) <a class="header-anchor" href="#_13-2-observaciones-sobre-las-fuentes-para-validar-no-se-modificaron" aria-label="Permalink to &quot;13.2 Observaciones sobre las fuentes (para validar; no se modificaron)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º</th><th>Observación</th><th>Fuentes</th></tr></thead><tbody><tr><td>OBS-01</td><td>DEC-068 indica que sueldos sigue en ProCoop hasta el corte administrativo, mientras que la tabla de etapas de T07 §9.7 deja sueldos en ProCoop también después de E3 &quot;si no fueron cortados&quot;. Por la regla R7 del plan <code>03</code>, prevalece la DEC; conviene alinear T07</td><td>DEC-068; T07 §9.7</td></tr><tr><td>OBS-02</td><td>T07 §9.6 punto 9 remite a &quot;§17.6&quot; para la aprobación del paralelo; el criterio está en T07 §17.4</td><td>T07 §9.6, §17.4</td></tr><tr><td>OBS-03</td><td>DEC-088 ubica la primera migración real de LAG después de O7 y el corte por etapas hasta O11, mientras que CTR-MIG-06 sitúa &quot;paralelo, by-pass y corte final en O11&quot;. No queda explícito si el corte comercial de LAG puede ocurrir antes de O11. <strong>Resuelta:</strong> sí, por servicio, tras el cierre de O7 (CTR-MIG-06 corregido; DEC-089)</td><td>DEC-088; T07 CTR-MIG-06; <code>03</code> §15.2</td></tr><tr><td>OBS-04</td><td>ESC-COB-L05 compara un ciclo completo de LAG, mientras que la aprobación del paralelo exige 2 ciclos consecutivos (T07 §17.4; PRM-MIG-041). Este plan aplica el criterio de 2 ciclos. <strong>Resuelta:</strong> ESC-COB-L05 corregido a los ciclos de PRM-MIG-041</td><td>M07 §17.6; T07 §17.4</td></tr></tbody></table>',70))])}const R=c(u,[["render",m]]);export{f as __pageData,R as default};
